gU6(){return"\u0414\u043e 30 \u0441\u0435\u043a\u0443\u043d\u0434. \u0412\u0438\u0434\u044f\u0442 \u0442\u043e\u043b\u044c\u043a\u043e \u0442\u0440\u0435\u043d\u0435\u0440\u044b \u0441\u043f\u043e\u0440\u0442\u0441\u043c\u0435\u043d\u0430."},
gQe(){return"\u041e\u0442\u043b\u0438\u0447\u043d\u043e! \u0422\u0440\u0435\u043d\u0435\u0440 \u0432\u0438\u0434\u0438\u0442 \u0432 \u043f\u0440\u0438\u043b\u043e\u0436\u0435\u043d\u0438\u0438, \u0447\u0442\u043e \u0442\u044b \u0432 \u043f\u0443\u0442\u0438."},
gQ5(){return"\u041a\u043e\u0433\u0434\u0430 \u0441\u043f\u043e\u0440\u0442\u0441\u043c\u0435\u043d \u043d\u0430\u0431\u0438\u0440\u0430\u0435\u0442 \u044d\u0442\u043e \u0447\u0438\u0441\u043b\u043e \u043e\u043f\u043e\u0437\u0434\u0430\u043d\u0438\u0439, \u0442\u0440\u0435\u043d\u0435\u0440 \u0432\u0438\u0434\u0438\u0442 \u043f\u0440\u0435\u0434\u0443\u043f\u0440\u0435\u0436\u0434\u0435\u043d\u0438\u0435 \u0432 \u043f\u0440\u0438\u043b\u043e\u0436\u0435\u043d\u0438\u0438. Jita \u043d\u0435 \u043d\u0430\u0437\u043d\u0430\u0447\u0430\u0435\u0442 \u043d\u0430\u043a\u0430\u0437\u0430\u043d\u0438\u0439, \u0440\u0435\u0448\u0435\u043d\u0438\u0435 \u0437\u0430 \u0442\u0440\u0435\u043d\u0435\u0440\u043e\u043c."},
